import type { LeaderboardEntry } from "@cicord/client";
import { useMe, useRouteQuery } from "@cicord/react";
import { Avatar, Button, Notice, Spinner } from "@cicord/ui";
import { useT } from "../i18n/index.tsx";
import { useNumber } from "../portal.tsx";

/**
 * Public leaderboard of the `levels` plugin (`GET /leaderboard`, access: public): works
 * logged out. The instance is discovered through `PortalServer.plugins`; the query and the
 * response are typed by the plugin's route contract (src/cicord-routes.d.ts, generated by
 * `cicord portal typegen`).
 */
export function Leaderboard() {
  const t = useT();
  const board = useRouteQuery("levels", "GET /leaderboard", { query: { limit: 50 } });
  const me = useMe();
  const items = board.data?.items ?? [];
  const max = Math.max(1, ...items.map((e) => e.xp));

  return (
    <div className="page leaderboard">
      <header className="page__header">
        <h1>{t.leaderboard.title}</h1>
        <p>{t.leaderboard.lead}</p>
      </header>
      {board.status === "error" ? (
        <Notice
          tone="error"
          title={t.leaderboard.failed}
          action={
            <Button size="sm" variant="secondary" onClick={() => void board.refetch()}>
              {t.onboarding.retry}
            </Button>
          }
        />
      ) : !board.data ? (
        <div className="portal-loading portal-loading--inline">
          <Spinner size="lg" label={t.loading} />
        </div>
      ) : items.length === 0 ? (
        <Notice>{t.leaderboard.empty}</Notice>
      ) : (
        <>
          <ol className="podium" aria-label="Top 3">
            {items.slice(0, 3).map((e) => (
              <PodiumEntry key={e.userId} entry={e} you={e.userId === me.data?.user.id} />
            ))}
          </ol>
          {items.length > 3 ? (
            <ol className="ranking" start={4}>
              {items.slice(3).map((e) => (
                <RankRow key={e.userId} entry={e} max={max} you={e.userId === me.data?.user.id} />
              ))}
            </ol>
          ) : null}
        </>
      )}
    </div>
  );
}

const MEDALS = ["#f5c542", "#c3cad6", "#d58d55"];

function PodiumEntry({ entry, you }: { entry: LeaderboardEntry; you: boolean }) {
  const t = useT();
  const fmt = useNumber();
  return (
    <li className={`podium__entry podium__entry--${entry.rank}`} data-you={you || undefined}>
      <span className="podium__rank" aria-label={`#${entry.rank}`}>
        {entry.rank}
      </span>
      <Avatar
        src={entry.avatarUrl ?? undefined}
        name={entry.displayName}
        size={64}
        ring={MEDALS[entry.rank - 1] ?? "var(--cicord-primary)"}
      />
      <span className="podium__name">
        {entry.displayName}
        {you ? <small> ({t.leaderboard.you})</small> : null}
      </span>
      <span className="podium__level">{t.me.level(entry.level)}</span>
      <span className="podium__xp">{t.me.xp(fmt(entry.xp))}</span>
    </li>
  );
}

function RankRow({ entry, max, you }: { entry: LeaderboardEntry; max: number; you: boolean }) {
  const t = useT();
  const fmt = useNumber();
  return (
    <li className="ranking__row" data-you={you || undefined}>
      <span className="ranking__rank">{entry.rank}</span>
      <Avatar src={entry.avatarUrl ?? undefined} name={entry.displayName} size={36} />
      <span className="ranking__who">
        <span className="ranking__name">
          {entry.displayName}
          {you ? <small> ({t.leaderboard.you})</small> : null}
        </span>
        <span className="ranking__bar" aria-hidden="true">
          <span style={{ width: `${Math.max(4, (entry.xp / max) * 100)}%` }} />
        </span>
      </span>
      <span className="ranking__level">{t.me.level(entry.level)}</span>
      <span className="ranking__xp">{t.me.xp(fmt(entry.xp))}</span>
    </li>
  );
}
